 80	+                } else if (reservation.ratePlan() == RatePlan.NON_REFUNDABLE) {
 81	+                    nonRefundableReservations++;
 82	+                    nonRefundableAmount = nonRefundableAmount.add(reservation.amountKept());
 83	+                }
 84	+            }
 85	+        }
 86	+
 87	+        StringBuilder csv = new StringBuilder();
 88	+        csv.append("Pousada Maré Alta,rate-plans,").append(month).append('\n');
 89	+        csv.append("rate_plan,reservations,amount\n");
 90	+        csv.append("STANDARD,").append(standardReservations).append(',')
 91	+                .append(standardAmount.toPlainString()).append('\n');
 92	+        csv.append("NON_REFUNDABLE,").append(nonRefundableReservations).append(',')
 93	+                .append(nonRefundableAmount.toPlainString()).append('\n');
