126	+import java.math.RoundingMode;
127	+import java.time.YearMonth;
128	+import java.util.ArrayList;
129	+import java.util.Comparator;
130	+import java.util.List;
131	+
132	+/** The tourism tax charged by the municipality for each guest per night (CSV). */
133	+public final class TourismTaxReport {
134	+
135	+    private static final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
136	+    private final Rooms rooms;
137	+    private final ReservationStore store;
138	+
139	+    public TourismTaxReport(Rooms rooms, ReservationStore store) {
140	+        this.rooms = rooms;
141	+        this.store = store;
142	+    }
143	+
144	+    public String generate(YearMonth month) {
145	+        List<Reservation> taxable = new ArrayList<>();
146	+        for (Reservation reservation : store.all()) {
147	+            boolean keptMoney = reservation.amountKept().signum() > 0;
148	+            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
149	+            if (keptMoney && startsInMonth) {
150	+                taxable.add(reservation);
151	+            }
152	+        }
153	+        taxable.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
154	+
155	+        StringBuilder csv = new StringBuilder();
156	+        csv.append("Pousada Maré Alta,tourism-tax,").append(month).append('\n');
157	+        csv.append("reservation,room,check_in,check_out,guests,nights,tax\n");
158	+        BigDecimal totalTax = BigDecimal.ZERO.setScale(2);
159	+        for (Reservation reservation : taxable) {
160	+            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
161	+            long nights = reservation.checkOut().toEpochDay() - reservation.checkIn().toEpochDay();
162	+            BigDecimal tax = TAX_PER_GUEST_PER_NIGHT
163	+                    .multiply(BigDecimal.valueOf(reservation.guests()))
164	+                    .multiply(BigDecimal.valueOf(nights))
165	+                    .setScale(2, RoundingMode.HALF_UP);
166	+            csv.append(reservation.id()).append(',')
167	+                    .append(room.number()).append(',')
168	+                    .append(reservation.checkIn()).append(',')
169	+                    .append(reservation.checkOut()).append(',')
170	+                    .append(reservation.guests()).append(',')
171	+                    .append(nights).append(',')
172	+                    .append(tax.toPlainString()).append('\n');
173	+            totalTax = totalTax.add(tax);
174	+        }
175	+        csv.append("total,").append(totalTax.toPlainString()).append('\n');
176	+        return csv.toString();
177	+    }
178	+}
